import { FC, HTMLAttributes } from 'react';
import { useParams } from 'react-router-dom';

import cn from 'classnames';

import { CollectionPageTitle } from 'entities/Collection';
import { MOCK_COLLECTIONS } from 'shared/consts/MOCK_FOR_CATALOG';
import { Content, Page } from 'shared/ui';
import { CollectionPostList } from 'widgets/CollectionList';

interface ICollectionProps extends HTMLAttributes<HTMLDivElement> {}

export const Collection: FC<ICollectionProps> = ({ className, ...props }) => {
	const { id } = useParams();

	// TODO:
	const collection = MOCK_COLLECTIONS.find((col) => col.id === id) || MOCK_COLLECTIONS[0];

	return (
		<Page {...props} className={cn(className)}>
			<CollectionPageTitle collection={collection} />
			<Content>
				<CollectionPostList data={collection} />
			</Content>
		</Page>
	);
};

export default Collection;
