import { FC, HTMLAttributes, useState } from 'react';
import { useTranslation } from 'react-i18next';

import { Avatar, Badge, Button, Flex, Popover, Typography } from 'antd';
import type { ButtonColorType } from 'antd/es/button/buttonHelpers';
import cn from 'classnames';

import ChatIcon from 'assets/images/icons/chat.svg?react';
import DeleteIcon from 'assets/images/icons/delete.svg?react';
import DuplicateIcon from 'assets/images/icons/duplicate.svg?react';
import EditIcon from 'assets/images/icons/edit.svg?react';
import MoreIcon from 'assets/images/icons/more.svg?react';
import MoveIcon from 'assets/images/icons/move.svg?react';
import SendIcon from 'assets/images/icons/send.svg?react';
import { MOCK_IPost } from 'shared/consts/MOCK_FOR_CATALOG';

import styles from './CollectionPostCard.module.scss';

interface ICollectionPostCardProps extends HTMLAttributes<HTMLDivElement> {
	post: MOCK_IPost;
}

export const CollectionPostCard: FC<ICollectionPostCardProps> = ({ className, post, ...props }) => {
	const { description, image, name } = post;
	const { t } = useTranslation();
	const [expanded, setExpanded] = useState(false);

	const handleEditClick = () => {};
	const handleDuplicateClick = () => {};
	const handleMoveClick = () => {};
	const handleChatClick = () => {};
	const handleDeleteClick = () => {};

	const postActions = [
		{ name: t('Изменить'), icon: <EditIcon />, action: handleEditClick },
		{ name: t('Дублировать'), icon: <DuplicateIcon />, action: handleDuplicateClick },
		{ name: t('Переместить'), icon: <MoveIcon />, action: handleMoveClick },
		{ name: t('Отправить в чат с ботом'), icon: <ChatIcon />, action: handleChatClick },
		{ name: t('Удалить'), icon: <DeleteIcon />, action: handleDeleteClick, color: 'danger' as ButtonColorType },
	];

	return (
		<div {...props} className={cn(className, styles.collectionPostCard)}>
			<Flex gap={8} className={styles.collectionPostCard__info}>
				<Avatar
					shape="square"
					size={76}
					className={styles.collectionPostCard__img}
					icon={<img src={image} alt={name} />}
				/>
				<Typography.Paragraph
					className={styles.collectionPostCard__lineClamp}
					ellipsis={{
						rows: 4,
						expandable: 'collapsible',
						expanded,
						onExpand: (_, info) => setExpanded(info.expanded),
					}}>
					{description}
				</Typography.Paragraph>
			</Flex>
			<Flex
				gap={4}
				justify={'space-between'}
				className={cn(styles.collectionPostCard__part, styles.collectionPostCard__schedule)}>
				<Badge status="processing" text={t('Опубликуется')} />
				<Typography.Text type="secondary">11:59 · 15 июл</Typography.Text>
			</Flex>
			<Flex gap={4} className={styles.collectionPostCard__part}>
				{/*TODO:*/}
				<Flex gap={8} align="center">
					<Avatar
						shape="circle"
						size={32}
						className={styles.collectionPostCard__img}
						icon={<img src={image} alt={name} />}
					/>
					<Typography.Text ellipsis>Nike – Just do it today and tomorrow</Typography.Text>
				</Flex>
			</Flex>
			<Flex gap={4} className={styles.collectionPostCard__part}>
				<Popover
					trigger="click"
					content={
						<Flex vertical>
							{postActions.map((action) => (
								<Button
									block
									icon={action.icon}
									color={action.color || 'default'}
									variant="text"
									onClick={action.action}
									className={styles.collectionPostCard__tal}>
									{action.name}
								</Button>
							))}
						</Flex>
					}>
					<Button style={{ flexShrink: 0 }} icon={<MoreIcon />} />
				</Popover>
				<Button style={{ flexShrink: 0 }} icon={<SendIcon />} />
				<Button block>{t('Запланировать пост')}</Button>
			</Flex>
		</div>
	);
};
