import { FC, HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';

import { Flex } from 'antd';

import { CollectionPostCard } from 'entities/Collection';
import { CollectionFilters } from 'features/Filters';
import { MOCK_ICollection } from 'shared/consts/MOCK_FOR_CATALOG';
import { EMainRoutes } from 'shared/typings';
import { ButtonStyleLink, NoResults } from 'shared/ui';

interface ICollectionPostListProps extends HTMLAttributes<HTMLDivElement> {
	data: MOCK_ICollection;
}

export const CollectionPostList: FC<ICollectionPostListProps> = ({ data }) => {
	const { t } = useTranslation();

	return (
		<Flex vertical gap={16}>
			<CollectionFilters />
			{!data.items.length && (
				<NoResults
					text={t('Нет постов')}
					subtext={t('Вы пока не добавили еще ни одного поста')}
					goTo={
						<ButtonStyleLink type="primary" to={`/${EMainRoutes.CATALOG}`} block size="large">
							{t('Добавить из каталога')}
						</ButtonStyleLink>
					}
				/>
			)}
			<Flex gap={8} vertical>
				{data.items.map((post) => (
					<CollectionPostCard post={post} />
				))}
			</Flex>
		</Flex>
	);
};
