import { FC, HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';

import { Button, Flex, Popover, Typography } from 'antd';
import type { ButtonColorType } from 'antd/es/button/buttonHelpers';
import cn from 'classnames';

import DeleteIcon from 'assets/images/icons/delete.svg?react';
import DuplicateIcon from 'assets/images/icons/duplicate.svg?react';
import MoreIcon from 'assets/images/icons/more.svg?react';
import SettingsIcon from 'assets/images/icons/settings.svg?react';
import noNameImg from 'assets/images/no_name.webp';
import { MOCK_ICollection } from 'shared/consts/MOCK_FOR_CATALOG.ts';

import styles from './CollectionPageTitle.module.scss';

interface ICollectionPageTitleProps extends HTMLAttributes<HTMLDivElement> {
	collection: MOCK_ICollection;
}

export const CollectionPageTitle: FC<ICollectionPageTitleProps> = ({ className, collection }) => {
	const { t } = useTranslation();

	const handleTuneClick = () => {};
	const handleDuplicateClick = () => {};
	const handleDeleteClick = () => {};

	const actions = [
		{ name: t('Настроить'), icon: <SettingsIcon />, action: handleTuneClick },
		{ name: t('Дублировать'), icon: <DuplicateIcon />, action: handleDuplicateClick },
		{ name: t('Удалить'), icon: <DeleteIcon />, action: handleDeleteClick, color: 'danger' as ButtonColorType },
	];

	return (
		<Flex gap={8} className={cn(className, styles.collectionPageTitle)}>
			<img src={noNameImg} alt={''} width={60} height={60} />
			<div className={styles.collectionPageTitle__text}>
				<Typography.Title level={3} style={{ margin: 0 }}>
					{collection.name}
				</Typography.Title>
				<Typography.Text type="secondary">
					{t('Постов')}: {collection.items.length}
				</Typography.Text>
			</div>
			<Popover
				trigger="click"
				content={
					<Flex vertical>
						{actions.map((action) => (
							<Button
								block
								icon={action.icon}
								color={action.color || 'default'}
								variant="text"
								onClick={action.action}
								className={styles.collectionPageTitle__tal}>
								{action.name}
							</Button>
						))}
					</Flex>
				}>
				<Button style={{ flexShrink: 0 }} icon={<MoreIcon />} />
			</Popover>
		</Flex>
	);
};
