import { FC, HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';

import { Flex, Input, Select } from 'antd';

import { EFilters, OPTIONS_MAX_HEIGHT_NOTIFICATIONS, useFilters } from 'features/Filters';

interface ICollectionFiltersProps extends HTMLAttributes<HTMLDivElement> {}

export const CollectionFilters: FC<ICollectionFiltersProps> = ({ ...props }) => {
	const { t } = useTranslation();
	const { getFilterValue, onFilterChange } = useFilters(true);

	const options = [{ label: '456', value: '0' }]; //TODO:
	const statusOptions = [{ label: 'lorem', value: '0' }]; //TODO:

	return (
		<Flex {...props} vertical gap={8}>
			<Input.Search
				placeholder={t('Поиск')}
				onSearch={(value) => onFilterChange(EFilters.SEARCH, value)}
				value={getFilterValue(EFilters.SEARCH) || ''}
				allowClear
				size="large"
			/>
			<Select
				value={getFilterValue(EFilters.STATUS)}
				options={statusOptions}
				onChange={(value) => onFilterChange(EFilters.STATUS, value)}
				size="large"
				listHeight={OPTIONS_MAX_HEIGHT_NOTIFICATIONS}
				allowClear
				placeholder={t('Все статусы постов')}
			/>
			<Select
				value={getFilterValue(EFilters.CATEGORY)}
				options={options}
				onChange={(value) => onFilterChange(EFilters.CATEGORY, value)}
				size="large"
				listHeight={OPTIONS_MAX_HEIGHT_NOTIFICATIONS}
				allowClear
				placeholder={t('Все каналы и группы')}
			/>
		</Flex>
	);
};
